"""Observe actual C# nodes; private cache representation is unrestricted."""
from harness_random04 import uniform_parts
CORE=r'''
static class Nodes4 {
public sealed record Snapshot(RandomNode? Root,List<RandomNode> Nodes,List<(int Data,RandomNode? Left,RandomNode? Right)> Links,List<int> Values,Dictionary<RandomNode,int> Rank);
public static void Check(bool ok,string message){if(!ok)throw new InvalidOperationException(message);}
public static Snapshot Take(RandomBst actor){var root=actor.Root;var pending=new Stack<RandomNode>();if(root is not null)pending.Push(root);var nodes=new List<RandomNode>();var links=new List<(int,RandomNode?,RandomNode?)>();var seen=new HashSet<RandomNode>(ReferenceEqualityComparer.Instance);while(pending.Count>0){var node=pending.Pop();Check(seen.Add(node)&&nodes.Count<1000,"Root must be a finite proper tree");nodes.Add(node);links.Add((node.Data,node.Left,node.Right));if(node.Right is not null)pending.Push(node.Right);if(node.Left is not null)pending.Push(node.Left);}var ordered=new List<RandomNode>();var stack=new Stack<RandomNode>();var current=root;while(current is not null||stack.Count>0){while(current is not null){stack.Push(current);current=current.Left;}current=stack.Pop();ordered.Add(current);current=current.Right;}var values=ordered.Select(n=>n.Data).ToList();for(int i=1;i<values.Count;++i)Check(values[i-1]<=values[i],"Maintain BST inorder");var rank=new Dictionary<RandomNode,int>(ReferenceEqualityComparer.Instance);for(int i=0;i<ordered.Count;++i)rank.Add(ordered[i],i);return new(root,nodes,links,values,rank);}
public static int[] Query(RandomBst actor,Snapshot before,RandomNode? node){Check(ReferenceEquals(actor.Root,before.Root),"Queries preserve Root");for(int i=0;i<before.Nodes.Count;++i){var old=before.Nodes[i];var raw=before.Links[i];Check(old.Data==raw.Data&&ReferenceEquals(old.Left,raw.Left)&&ReferenceEquals(old.Right,raw.Right),"Queries preserve Data and links");}Check(node is null||before.Rank.ContainsKey(node),"Return actual current node");return node is null?[]:[node.Data];}
public static object? Basic(RandomBst actor,string operation,int[] args){if(operation=="Insert"){Action<int> insert=actor.Insert;insert(args[0]);return null;}if(operation=="Delete"){Func<int,bool> delete=actor.Delete;return delete(args[0]);}var before=Take(actor);if(operation=="Find")return Query(actor,before,actor.Find(args[0]));if(operation=="GetRandomNode")return Query(actor,before,actor.GetRandomNode());throw new Exception("Unknown operation");}
public static object Delta(List<int> before,List<int> after){int i=0,j=0;var added=new List<int>();var removed=new List<int>();while(i<before.Count&&j<after.Count){if(before[i]==after[j]){++i;++j;}else if(before[i]<after[j])removed.Add(before[i++]);else added.Add(after[j++]);}removed.AddRange(before.Skip(i));added.AddRange(after.Skip(j));return new {added,removed,count=after.Count};}
public static string[] Operations=[];public static int[][] Arguments=[];public static List<int> Values=[];
public static RandomBst Build(){var actor=new RandomBst();for(int i=1;i<Operations.Length;++i)Basic(actor,Operations[i],Arguments[i]);return actor;}
public static object Run(JsonElement row){var args=row.GetProperty("arguments");var operations=JsonSerializer.Deserialize<string[]>(args[0].GetRawText())!;var arguments=JsonSerializer.Deserialize<int[][]>(args[1].GetRawText())!;uint seed=0x411b57;RandomSource.Draw=(lower,upper)=>{Check(0<=lower&&lower<=upper,"Use valid inclusive bounds");seed=unchecked(seed*1664525+1013904223);return lower+(int)(((ulong)seed*((ulong)((long)upper-lower+1)))>>32);};var actor=new RandomBst();var before=Take(actor);var results=new List<object?>{null};var changes=new List<object>{Delta([],before.Values)};for(int i=1;i<operations.Length;++i){if(operations[i]=="GetRandomNode"){Operations=operations[..i];Arguments=arguments[..i];Values=before.Values.ToList();var saved=RandomSource.Draw;try{RandomAudit4_11.Run(JsonSerializer.SerializeToElement(new {arguments=new[]{Enumerable.Range(0,before.Values.Count).ToArray()}}));}finally{RandomSource.Draw=saved;}Check(ReferenceEquals(actor.Root,before.Root),"Instances own independent state");}results.Add(Basic(actor,operations[i],arguments[i]));var after=Take(actor);changes.Add(Delta(before.Values,after.Values));before=after;}return new {actual=new {results,finalValues=before.Values},changes,mutationOk=true,uniformOk=true};}
}
class Solution_4_11 {RandomBst? actor;public void Shuffle(int[] array){actor??=Nodes4.Build();var before=Nodes4.Take(actor);Nodes4.Check(before.Values.SequenceEqual(Nodes4.Values)&&array.Length==before.Values.Count,"Preserve operation-prefix multiset");var chosen=actor.GetRandomNode();Nodes4.Query(actor,before,chosen);if(array.Length==0){Nodes4.Check(chosen is null,"Empty query returns null");return;}Nodes4.Check(chosen is not null,"Nonempty query returns current node");int selected=before.Rank[chosen!];var remaining=Enumerable.Range(0,array.Length).Where(i=>i!=selected).ToArray();for(int i=remaining.Length-1;i>0;--i){int other=RandomSource.GetRandom(0,i);(remaining[i],remaining[other])=(remaining[other],remaining[i]);}array[0]=selected;remaining.CopyTo(array,1);}}
'''
def parts(code):
    outside,inside=uniform_parts('csharp',code+CORE)
    return outside,'static object ExecuteRandomBst4(JsonElement row)=>Nodes4.Run(row);\n'
